mapper.select:
SELECT id, student_id, goal_type, direction_id, name, status, chosen_at, version_no, created_at, updated_at
FROM student_goal
WHERE id = #{id}

SELECT id, student_id, goal_type, direction_id, name, status, chosen_at, version_no, created_at, updated_at
FROM student_goal
WHERE student_id = #{studentId}
  AND goal_type = #{goalType}
  AND status = 'ACTIVE'
LIMIT 1

mapper.update:
UPDATE student_goal
SET direction_id = #{directionId},
    name = #{name},
    chosen_at = #{chosenAt},
    version_no = #{versionNo}
WHERE id = #{id}

mapper.select:
SELECT id, plan_id, student_id, month, title, task_type, est_hours, status, deadline,
       ability_tags_json, note, created_at, updated_at
FROM plan_task
WHERE student_id = #{studentId}

    AND month = #{month}


    AND status = #{status}

ORDER BY month ASC, created_at ASC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM plan_task
WHERE student_id = #{studentId}

    AND month = #{month}


    AND status = #{status}

SELECT id, task_id, done_desc, gains, difficulties, proof_url, checked_in_at, created_at
FROM task_checkin
WHERE id = #{id}

SELECT id, student_id, type, title, content, is_read, created_at
FROM reminder
WHERE id = #{id}

SELECT id, student_id, type, title, content, is_read, created_at
FROM reminder
WHERE student_id = #{studentId}

    AND is_read = 0

ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM reminder
WHERE student_id = #{studentId}

    AND is_read = 0
